#include "postquantiquecoin/storage/WalletStorage.h"
#include "postquantiquecoin/storage/FileStorage.h"
namespace pqc { WalletStorage::WalletStorage(std::filesystem::path p):path_(std::move(p)){} Result<void> WalletStorage::SaveEncryptedWallet(const std::vector<uint8_t>& b) const { return AtomicSave(b); } Result<std::vector<uint8_t>> WalletStorage::LoadEncryptedWallet() const { return FileStorage::ReadFile(path_); } bool WalletStorage::Exists() const { return FileStorage::FileExists(path_); } Result<std::filesystem::path> WalletStorage::Backup(const std::filesystem::path& dst) const { if(dst.empty()) return FileStorage::BackupFile(path_); auto b=FileStorage::ReadFile(path_); if(b.IsErr()) return Result<std::filesystem::path>::Err(b.Error()); auto w=FileStorage::AtomicWrite(dst,b.Value()); if(w.IsErr()) return Result<std::filesystem::path>::Err(w.Error()); return Result<std::filesystem::path>::Ok(dst); } Result<void> WalletStorage::AtomicSave(const std::vector<uint8_t>& b) const { return FileStorage::AtomicWrite(path_,b); } const std::filesystem::path& WalletStorage::Path() const { return path_; } }
